template <typename T> void Relay(T&& value);
template <typename T> void Store(const T&& value);
template <typename T> struct Box { void Set(T&& value); };

// Мини-проверка: где T выводится по правилу forwarding reference?
// Ответ: у Relay. У Store форма const T&&; у Set тип T уже задан Box<T>.
// Одних символов && недостаточно: важны форма параметра и контекст вывода.
